module serial2parallel(
    input clk, 
    input rst_n, 
    input din_serial, 
    input din_valid, 
    output reg [7:0] dout_parallel, 
    output reg dout_valid
);
// Internal signals
reg [3:0] cnt;
reg valid;
// Sequential logic
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        cnt <= 0;
        valid <= 0;
        dout_parallel <= 0;
    end else begin
        if (din_valid) begin
            dout_parallel[cnt] <= din_serial;
            cnt <= cnt + 1;
            if (cnt == 7) begin
                valid <= 1;
                cnt <= 0;
            end
        end else begin
            valid <= 0;
        end
    end
end
// Output assignment
always @(*) begin
    dout_valid = valid;
end
endmodule
